mapper.select:
select fex.*, fex.last_update_date as last_date, (SELECT su.description FROM sys_user su where su.user_id = fex.last_updated_by ) as last_person, (SELECT fc.currency_name FROM fnd_currency fc where fc.currency_code = fex.currency) currency_n,
(SELECT fc.currency_name FROM fnd_currency fc where fc.currency_code = fex.foreign_currency) foreign_currency_n
from fnd_exchange_rate fex
1=1
and fex.exchange_date >= #{exchangeDateFrom}
and fex.exchange_date <= #{exchangeDateTo}
and fex.foreign_currency = #{foreignCurrency}
order by fex.exchange_date desc

SELECT gs.functional_currency as currency FROM fnd_company fc left join gld_financial_attribute gfa on fc.company_id = gfa.company_id left join gld_set_of_books gs on gfa.set_of_books_id = gs.set_of_books_id
1=1
and fc.company_id = #{companyId}

SELECT fer.*
FROM fnd_exchange_rate fer


    1=1

        and   fer.foreign_currency = #{foreignCurrency}


        and   fer.exchange_date= #{exchangeDate}
